<template>
  <div class="pt-wrap">
    <div class="hd">
      <div><div class="eb">NEW MODEL DEVELOPMENT</div><h1>Program Tracker</h1></div>
      <div class="meta">Data as of {{ meta.asOf }}<br>{{ meta.plant }}</div>
    </div>

    <div class="tabs">
      <button class="tb" :class="{ on: screen === 's1' }" @click="screen = 's1'">▢ Projects</button>
      <button class="tb" :class="{ on: screen === 's2' }" @click="screen = 's2'">⏱ Timeline</button>
      <button class="tb" :class="{ on: screen === 's3' }" @click="screen = 's3'">≡ Event Status</button>
    </div>

    <div class="sc" :class="{ on: screen === 's1' }" v-html="s1Html"></div>
    <div class="sc" :class="{ on: screen === 's2' }" v-html="s2Html"></div>
    <div class="sc" :class="{ on: screen === 's3' }" v-html="s3Html"></div>
  </div>
</template>

<script>
import { PROJECTS, PARTS, MONTHS, YEARS, HEADER_META } from "@/data/programTrackerData.js";

const ic = {
  pie: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:5px"><path d="M21.21 15.89A10 10 0 118 2.83"/><path d="M22 12A10 10 0 0012 2v10z"/></svg>',
  bars: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:5px"><path d="M18 20V10M12 20V4M6 20v-6"/></svg>',
  line: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:5px"><path d="M3 3v18h18"/><path d="M7 14l3-3 3 3 5-6"/></svg>',
  part: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 00.34 1.87l.06.06a2 2 0 11-2.83 2.83l-.06-.06a1.7 1.7 0 00-1.87-.34 1.7 1.7 0 00-1 1.55V21a2 2 0 01-4 0v-.09A1.7 1.7 0 009 19.4a1.7 1.7 0 00-1.87.34l-.06.06a2 2 0 11-2.83-2.83l.06-.06A1.7 1.7 0 004.6 15a1.7 1.7 0 00-1.55-1H3a2 2 0 010-4h.09A1.7 1.7 0 004.6 9a1.7 1.7 0 00-.34-1.87l-.06-.06a2 2 0 112.83-2.83l.06.06A1.7 1.7 0 009 4.6a1.7 1.7 0 001-1.55V3a2 2 0 014 0v.09a1.7 1.7 0 001 1.55 1.7 1.7 0 001.87-.34l.06-.06a2 2 0 112.83 2.83l-.06.06A1.7 1.7 0 0019.4 9a1.7 1.7 0 001.55 1H21a2 2 0 010 4h-.09a1.7 1.7 0 00-1.55 1z"/></svg>',
};
const CLR = { done: "var(--ok)", pend: "var(--warn)", delayed: "var(--bad)", na: "var(--faint)" };

function todayPct() {
  const d = new Date();
  const M = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const key = M[d.getMonth()] + "'" + String(d.getFullYear()).slice(2);
  const i = MONTHS.indexOf(key);
  if (i < 0) return -100;
  const dim = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  return ((i + d.getDate() / dim) / MONTHS.length) * 100;
}
const cls = (s) => (s === "On Track" ? "p-ok" : s === "Potential Delay" ? "p-wn" : "p-bd");
const pill = (s) => `<span class="pill ${cls(s)}">${s}</span>`;
function cell(m) {
  if (!m) return `<td class="dt">\u2014</td>`;
  return `<td><div class="dt" style="color:${CLR[m.s]}">${m.d}</div>${m.n ? `<div class="nt">${m.n}</div>` : ""}</td>`;
}
function taskStats(parts, key) {
  const s = { pend: 0, over: 0, late: 0, done: 0 };
  parts.forEach((pt) => {
    const entries = key ? [[key, pt.ms[key]]] : Object.entries(pt.ms).filter(([k]) => k !== "PP0");
    entries.forEach(([, m]) => {
      if (!m || m.s === "na") return;
      if (m.s === "done") s.done++;
      else if (m.s === "delayed") s.over++;
      else if (m.n) s.late++;
      else s.pend++;
    });
  });
  s.total = s.pend + s.over + s.late + s.done;
  return s;
}
function pieHtml(s, title) {
  const segs = [["Pending", s.pend, "var(--acc)"],["Overdue", s.over, "var(--bad)"],["Late Start", s.late, "var(--warn)"],["Completed", s.done, "var(--ok)"]];
  let acc = 0, C = 2 * Math.PI * 36, arcs = "";
  segs.forEach(([, v, cc]) => {
    if (!v) return;
    const L = (v / s.total) * C;
    arcs += `<circle cx="50" cy="50" r="36" fill="none" stroke="${cc}" stroke-width="20" stroke-dasharray="${L} ${C - L}" stroke-dashoffset="${-acc}" transform="rotate(-90 50 50)"/>`;
    acc += L;
  });
  const bars = segs.map(([nm, v, cc]) => `<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">
      <div style="width:70px;font-size:10.5px;color:var(--dim)">${nm}</div>
      <div class="bar" style="flex:1"><i style="width:${s.total ? (v / s.total) * 100 : 0}%;background:${cc}"></i></div>
      <div style="width:20px;text-align:right;font-family:var(--m);font-size:10.5px;color:var(--dim)">${v}</div></div>`).join("");
  return `<div class="pnl" style="margin:0"><h3><span>${ic.pie}${title}</span></h3>
      <div style="display:flex;align-items:center;gap:16px">
       <svg width="100" height="100" viewBox="0 0 100 100">${arcs}</svg>
       <div style="flex:1">${bars}</div></div></div>`;
}

export default {
  name: "ProgramTrackerTab",
  data() {
    return { screen: "s1", meta: HEADER_META };
  },
  computed: {
    s1Html() {
      const t = PROJECTS.length;
      const del = PROJECTS.filter((p) => p.status === "Delayed").length;
      const pot = PROJECTS.filter((p) => p.status === "Potential Delay").length;
      const ok = PROJECTS.filter((p) => p.status === "On Track").length;
      const late = Math.round(((del + pot) / t) * 100);
      const avg = Math.round(PROJECTS.reduce((a, p) => a + p.progress, 0) / t);
      const cust = [...new Set(PROJECTS.map((p) => p.customer))].length;

      const kpi = `<div class="kpis">
   <div class="k" style="--c:var(--acc)"><div class="l">Total Projects</div><div class="v">${t}</div><div class="s">${cust} customers</div></div>
   <div class="k" style="--c:var(--ok)"><div class="l">On Track</div><div class="v">${ok}</div><div class="s">no open risk</div></div>
   <div class="k" style="--c:var(--warn)"><div class="l">Potential Delay</div><div class="v">${pot}</div><div class="s">watch list</div></div>
   <div class="k" style="--c:var(--bad)"><div class="l">Delayed</div><div class="v">${del}</div><div class="s">needs escalation</div></div>
   <div class="k" style="--c:var(--bad)"><div class="l">Late Projects</div><div class="v">${late}%</div><div class="s">${del + pot} of ${t}</div></div>
   <div class="k" style="--c:var(--vio)"><div class="l">Avg Progress</div><div class="v">${avg}%</div><div class="s">across portfolio</div></div>
  </div>`;

      const segs = [[ok, "#1E8E5A"],[pot, "#B4690A"],[del, "#C43B3B"]];
      let a = 0, C = 2 * Math.PI * 38, dn = "";
      segs.forEach(([v, c]) => {
        const L = (v / t) * C;
        dn += `<circle cx="60" cy="60" r="38" fill="none" stroke="${c}" stroke-width="15" stroke-dasharray="${L} ${C - L}" stroke-dashoffset="${-a}" transform="rotate(-90 60 60)"/>`;
        a += L;
      });

      const mp = {};
      PROJECTS.forEach((p) => (mp[p.mpTarget] = (mp[p.mpTarget] || 0) + 1));
      const mx = Math.max(...Object.values(mp));
      const bars = Object.entries(mp).map(([m, v]) => `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:6px">
      <div style="font-family:var(--m);font-size:11px;color:var(--dim)">${v}</div>
      <div style="width:70%;height:${(v / mx) * 90}px;background:linear-gradient(180deg,var(--acc),#1E3F8F);border-radius:4px 4px 0 0"></div>
      <div style="font-family:var(--m);font-size:10px;color:var(--faint)">${m}</div>
    </div>`).join("");

      const charts = `<div style="display:grid;grid-template-columns:1fr 1.6fr;gap:16px;margin-bottom:16px">
   <div class="pnl" style="margin:0"><h3><span>${ic.pie}Project Status Mix</span></h3>
    <div style="display:flex;align-items:center;gap:22px">
     <svg width="120" height="120" viewBox="0 0 120 120">${dn}
      <text x="60" y="58" text-anchor="middle" fill="#1B1F27" font-size="22" font-family="Consolas" font-weight="700">${t}</text>
      <text x="60" y="74" text-anchor="middle" fill="#8A93A3" font-size="9" font-family="Consolas">PROJECTS</text></svg>
     <div style="display:flex;flex-direction:column;gap:9px;font-size:12px;color:var(--dim)">
      <div><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--ok);margin-right:8px"></span>On Track <b style="color:var(--tx);font-family:var(--m)">${ok}</b></div>
      <div><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--warn);margin-right:8px"></span>Potential Delay <b style="color:var(--tx);font-family:var(--m)">${pot}</b></div>
      <div><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--bad);margin-right:8px"></span>Delayed <b style="color:var(--tx);font-family:var(--m)">${del}</b></div>
     </div></div></div>
   <div class="pnl" style="margin:0"><h3><span>${ic.bars}Mass Production Schedule </span><span class="n">projects by MP target</span></h3>
    <div style="display:flex;align-items:flex-end;height:130px;gap:8px">${bars}</div></div>
  </div>`;

      const allT = taskStats(PARTS), delivT = taskStats(PARTS, "MP"),
        critT = taskStats(PARTS.filter((pt) => PROJECTS.find((pr) => pr.id === pt.pid && pr.status === "Delayed")));

      const tlOK = ok, tlPot = pot, tlDel = del;
      const topLevel = `<div class="pnl" style="margin:0"><h3><span>${ic.bars}Top Level Tasks</span></h3>
    <div style="display:flex;height:26px;border-radius:4px;overflow:hidden;background:var(--panel2)">
      ${tlOK ? `<div style="width:${(tlOK / t) * 100}%;background:var(--ok);display:flex;align-items:center;justify-content:center;color:#fff;font-family:var(--m);font-size:11px;font-weight:700">${tlOK}</div>` : ""}
      ${tlPot ? `<div style="width:${(tlPot / t) * 100}%;background:var(--warn);display:flex;align-items:center;justify-content:center;color:#fff;font-family:var(--m);font-size:11px;font-weight:700">${tlPot}</div>` : ""}
      ${tlDel ? `<div style="width:${(tlDel / t) * 100}%;background:var(--bad);display:flex;align-items:center;justify-content:center;color:#fff;font-family:var(--m);font-size:11px;font-weight:700">${tlDel}</div>` : ""}
    </div>
    <div style="display:flex;gap:14px;margin-top:10px;font-size:11px;color:var(--dim)">
      <div><i style="background:var(--ok)" class="dotsw"></i>On Track</div>
      <div><i style="background:var(--warn)" class="dotsw"></i>Potential Delay</div>
      <div><i style="background:var(--bad)" class="dotsw"></i>Delayed</div>
    </div></div>`;

      const weeks = 10, tot = allT.total || 1, doneN = allT.done;
      let pPts = [], aPts = [];
      for (let i = 0; i < weeks; i++) {
        const planned = Math.max(0, Math.round(tot - (tot / (weeks - 1)) * i));
        const actual = Math.max(tot - doneN, Math.round(tot - (doneN / (weeks - 1)) * Math.min(i, weeks - 3)));
        pPts.push(planned);
        aPts.push(actual);
      }
      const bw = 900, bh = 130, padL = 30, padB = 20, maxY = Math.max(...pPts, ...aPts, 1);
      const X = (i) => padL + (i / (weeks - 1)) * (bw - padL - 10);
      const Y = (v) => bh - padB - (v / maxY) * (bh - padB - 10);
      const path = (arr) => arr.map((v, i) => `${i === 0 ? "M" : "L"}${X(i)},${Y(v)}`).join(" ");
      const burndown = `<div class="pnl"><h3><span>${ic.line}Burn Down </span><span class="n">remaining tasks / week</span></h3>
    <svg viewBox="0 0 ${bw} ${bh}" style="width:100%;height:150px">
      <path d="${path(pPts)}" fill="none" stroke="var(--acc)" stroke-width="2.5"/>
      <path d="${path(aPts)}" fill="none" stroke="var(--warn)" stroke-width="2.5" stroke-dasharray="4 3"/>
      ${pPts.map((v, i) => `<circle cx="${X(i)}" cy="${Y(v)}" r="3" fill="var(--acc)"/>`).join("")}
      ${aPts.map((v, i) => `<circle cx="${X(i)}" cy="${Y(v)}" r="3" fill="var(--warn)"/>`).join("")}
    </svg>
    <div style="display:flex;gap:16px;font-size:11px;color:var(--dim)">
      <div><i style="background:var(--acc)" class="dotsw" style="border-radius:2px"></i>Planned</div>
      <div><i style="background:var(--warn)" class="dotsw"></i>Actual</div>
    </div></div>`;

      const extra = `<div class="chart-grid">${topLevel}${pieHtml(allT, "All Tasks")}</div>
   <div class="chart-grid">${pieHtml(delivT, "Tasks With Deliverables")}${pieHtml(critT, "Critical Tasks")}</div>
   ${burndown}`;

      return kpi + charts + extra;
    },

    s2Html() {
      const list = PARTS;
      const T = list.length;
      const okN = list.filter((p) => p.st !== "Delayed").length;
      const potN = list.filter((p) => p.st === "Potential Delay").length;
      const badL = list.filter((p) => p.st === "Delayed");
      const c1 = list.filter((p) => (p.ms.PP1_1 || {}).s === "done").length;
      const c2 = list.filter((p) => (p.ms.PP2 || {}).s === "done").length;
      const c3 = list.filter((p) => (p.ms.PP3 || {}).s === "done").length;
      const dtxt = badL.length ? badL.map((p, i) => `${String(i + 1).padStart(2, "0")} [${p.model} \u2013 ${p.bn}]`).join("<br>") : "\u2014";

      const band = `<div class="band">
   <div class="c"><div class="l">Total Parts</div><div class="v">${String(T).padStart(2, "0")}</div></div>
   <div class="c"><div class="l">Status OK<br>[As per Timeline]</div><div class="v" style="color:var(--ok)">${String(okN).padStart(2, "0")}</div></div>
   <div class="c"><div class="l">Potential Delay</div><div class="v" style="color:var(--warn)">${String(potN).padStart(2, "0")}</div></div>
   <div class="c wide"><div class="l">Delayed</div><div class="v">${dtxt}</div></div>
   <div class="c"><div class="l">PP1 Completed</div><div class="v">${String(c1).padStart(2, "0")}<span class="d">/${String(T).padStart(2, "0")}</span></div></div>
   <div class="c"><div class="l">PP2 Completed</div><div class="v">${String(c2).padStart(2, "0")}<span class="d">/${String(T).padStart(2, "0")}</span></div></div>
   <div class="c"><div class="l">PP3 Completed</div><div class="v">${String(c3).padStart(2, "0")}<span class="d">/${String(T).padStart(2, "0")}</span></div></div>
  </div>`;

      const yh = YEARS.map((y) => `<div style="flex:${y.n}">${y.y}</div>`).join("");
      const mh = MONTHS.map((m) => `<div>${m.split("'")[0]}</div>`).join("");

      const rows = list.map((p) => {
        const cells = MONTHS.map(() => `<div class="cl"></div>`).join("");
        let mk = "";
        ["PP1", "PP2", "PP3"].forEach((k) => {
          (p.g[k] || []).forEach((mo) => {
            const i = MONTHS.indexOf(mo);
            if (i < 0) return;
            const st = k === "PP1" ? "done" : p.st === "On Track" ? "pend" : "delayed";
            mk += `<div class="mk" style="left:${((i + 0.5) / MONTHS.length) * 100}%">
          <div class="d" style="background:${CLR[st]}">${k.slice(2)}</div><div class="t">${mo}</div></div>`;
          });
        });
        if (p.g.MP) {
          const i = MONTHS.indexOf(p.g.MP);
          if (i >= 0) mk += `<div class="mk mp" style="left:${((i + 0.5) / MONTHS.length) * 100}%"><div class="d"></div><div class="t">MP</div></div>`;
        }
        const TL = todayPct();
        return `<div class="gr"><div class="lb"><div class="lbrow">
        <div class="lbimg">${ic.part}</div>
        <div style="flex:1;min-width:0">
          <div class="nm">${p.part}</div>
          <div class="sub">${p.model} ${pill(p.st)}</div>
        </div>
        <div class="lbcust">${p.cust}</div>
      </div></div><div class="trk">${cells}${mk}<div class="today" style="left:${TL}%"></div></div></div>`;
      }).join("");

      return band + `
   <div class="gw">
     <div class="gyr"><div class="lb"></div><div class="tr">${yh}</div></div>
     <div class="gmo"><div class="lb"><div class="lbrow"><div style="flex:1">Part</div><div class="lbcust" style="border-left:none">Cust.</div></div></div><div class="tr" style="position:relative">${mh}<div class="today" style="left:${todayPct()}%"></div><div class="todaycap" style="left:${todayPct()}%">TODAY</div></div></div>
     ${rows}</div>`;
    },

    s3Html() {
      const rows = PARTS.map((p, i) => `<tr>
    <td class="ctr dt">${i + 1}</td>
    <td class="dt">${p.loc}</td>
    <td class="bdg" style="margin-top:0">${p.model}</td>
    <td><div class="nm">${p.part}</div><div class="sub">${p.cust}</div></td>
    <td class="ctr"><div class="lbimg" style="margin:0 auto">${ic.part}</div></td>
    <td class="ctr dt">${p.vol}</td>
    <td class="ctr dt">${p.pl}</td>
    ${cell(p.ms.PP0)}${cell(p.ms.PP1_1)}${cell(p.ms.PP1_2)}${cell(p.ms.PP2)}
    ${cell(p.ms.QAV)}${cell(p.ms.PP3)}${cell(p.ms.MP)}
    <td class="rk">${p.rk}</td>
    <td class="bn">${pill(p.st)}<div style="margin-top:6px">${p.bn}</div></td></tr>`).join("");
      return `<div class="tw"><table class="ev"><thead><tr>
    <th>#</th><th>Location</th><th>Model</th><th>Part Name</th><th>Image</th><th>Vol/Day</th><th>PL</th>
    <th>PP0</th><th>PP1-1</th><th>PP1-2</th><th>PP2</th><th>Customer QAV</th>
    <th>PP3</th><th>MP</th><th>Remarks</th><th>Status / Bottleneck</th></tr></thead>
    <tbody>${rows}</tbody></table></div>`;
    },
  },
};
</script>

<style>
.pt-wrap{
  --bg:#F4F5F7; --panel:#FFFFFF; --panel2:#EEF0F3; --line:#DCE0E6;
  --tx:#1B1F27; --dim:#5B6472; --faint:#8A93A3;
  --ok:#1E8E5A; --okbg:#E3F5EC;
  --warn:#B4690A; --warnbg:#FBEEDB;
  --bad:#C43B3B; --badbg:#FBE5E5;
  --acc:#2F5FC7; --vio:#6A4FB0;
  --f:'Segoe UI',-apple-system,Arial,sans-serif;
  --m:'Consolas','SF Mono',monospace;
}
.pt-wrap *{box-sizing:border-box}
.pt-wrap{margin:0;background:var(--bg);color:var(--tx);font-family:var(--f);font-size:14px;padding-bottom:50px}
.pt-wrap .hd{display:flex;justify-content:space-between;align-items:center;padding:12px 24px}
.pt-wrap .hd .eb{font-family:var(--m);font-size:9.5px;color:var(--faint)}
.pt-wrap .hd h1{margin:0;font-size:16px;font-weight:600}
.pt-wrap .hd .meta{font-family:var(--m);font-size:10.5px;color:var(--dim);text-align:right;line-height:1.4}
.pt-wrap .tabs{display:flex;padding:0 24px;border-bottom:1px solid var(--line)}
.pt-wrap .tb{background:none;border:none;color:var(--dim);font-family:var(--f);font-size:12.5px;font-weight:600;padding:8px 14px;cursor:pointer;border-bottom:2px solid transparent}
.pt-wrap .tb:hover{color:var(--tx)}
.pt-wrap .tb.on{color:var(--tx);border-bottom-color:var(--warn)}
.pt-wrap .sc{padding:24px 30px;display:none}
.pt-wrap .sc.on{display:block}
.pt-wrap .pnl{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:18px 20px;margin-bottom:16px}
.pt-wrap .pnl h3{margin:0 0 14px;font-size:13px;font-weight:600;display:flex;justify-content:space-between}
.pt-wrap .pnl h3 .n{font-family:var(--m);font-weight:400;font-size:11px;color:var(--faint)}
.pt-wrap .kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:18px}
.pt-wrap .k{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:14px 16px;position:relative;overflow:hidden}
.pt-wrap .k::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--c,var(--acc))}
.pt-wrap .k .l{font-size:11px;color:var(--dim)}
.pt-wrap .k .v{font-family:var(--m);font-size:27px;font-weight:600;margin-top:6px}
.pt-wrap .k .s{font-size:11px;color:var(--faint);margin-top:2px}
.pt-wrap table{width:100%;border-collapse:collapse}
.pt-wrap th{text-align:left;font-size:10.5px;color:var(--faint);font-weight:700;padding:8px 10px;border-bottom:1px solid var(--line);white-space:nowrap}
.pt-wrap td{padding:11px 10px;border-bottom:1px solid var(--line);font-size:12.5px;vertical-align:middle}
.pt-wrap tbody tr:last-child td{border-bottom:none}
.pt-wrap tbody tr:hover{background:var(--panel2)}
.pt-wrap .nm{font-weight:600}
.pt-wrap .sub{font-size:11px;color:var(--dim);margin-top:2px}
