import dashboardApi from "../services/dashboardApi.js";
import { useDashboardStore } from "@/store/dashboardStore.js";
// const dashboardStore = useDashboardStore();
let initApp = {};
export let Space3DURL = "";
initApp.get3DSpaceURL = async function () {
  return new Promise((resolve, reject) => {
    try {
      window.requirejs(
        ["DS/i3DXCompassServices/i3DXCompassServices"],
        function (i3DXCompassServices) {
          i3DXCompassServices.getServiceUrl({
            serviceName: "3DSpace",
            // onComplete: function (url) {
            //   Space3DURL = url[0].url;
            //   console.log("3DSpace URL:", url);
            //   const baseUrl = (url[0].url || "").replace(/\/3dspace\/?$/i, "");

            //   // dashboardStore.setBaseUrl(baseUrl);
            //   store().setValue("baseUrl", baseUrl);
            //   resolve(url[0].url);
            // },
            onComplete: function (urls) {
              const currentHost = window.location.hostname.toLowerCase();

              const result = urls.find((item) => {
                if (!item.url) return false;

                initApp.store().setValue("Server", item.platformId);
                // On-Premise
                if (item.platformId === "OnPremise") {
                  return (
                    new URL(item.url).hostname.toLowerCase() === currentHost
                  );
                } else {
                  // Cloud
                  const currentTenant = currentHost
                    .split(".")[0]
                    .split("-")[0]
                    .toLowerCase();
                  return item.platformId.toLowerCase() === currentTenant;
                }
              });

              Space3DURL = result ? result.url : null;

              console.log("Selected 3DSpace URL:", Space3DURL);
              initApp.store().setValue("Space3DURL", Space3DURL);
              const baseUrl = (Space3DURL || "").replace(
                /\/(?:3dspace|enovia)\/?$/i,
                "",
              );
              initApp.store().setValue("baseUrl", baseUrl);
              resolve(Space3DURL);
            },
            onFailure: function (err) {
              console.error("Service URL Error:", err);
              reject(err);
            },
          });
        },
      );
    } catch (error) {
      reject(error);
    }
  });
};
initApp.getUserDetails = async function () {
  try {
    const user = await window.requirejs("DS/PlatformAPI/PlatformAPI").getUser();
    const userDetails = {
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      login: user.login,
    };
    // dashboardStore.setUser(userDetails);
    initApp.store().setValue("user", userDetails);
    // console.log("User Details:", dashboardStore.user);
    return userDetails;
  } catch (e) {
    throw new Error(e.message);
  }
};

initApp.userCtxCollabspaces = async function (widget) {
  try {
    let data = await dashboardApi.getCollabspaces();
    let role = data.preferredcredentials.role.name;
    let organization = data.preferredcredentials.organization.name;
    let collabspace = data.preferredcredentials.collabspace.name;
    let ctx = `ctx::${role}.${organization}.${collabspace}`;
    const formattedOutput = extractCollabspaceInfo(data);
    const formattedArray = formattedOutput.map((item) => ({
      label: item,
      value: `ctx::${item}`,
    }));
    widget.addPreference({
      name: "ctx_credentials",
      type: "list",
      label: "Credentials",
      defaultValue: ctx,
      options: formattedArray,
    });
  } catch (err) {
    throw new Error("CTX is missing!");
  }
};

function extractCollabspaceInfo(data) {
  let results = [];
  try {
    data.collabspaces.forEach((collabspace) => {
      const spaceName = collabspace.name;
      collabspace.couples.forEach((couple) => {
        const organizationName = couple.organization.name;
        const roleName = couple.role.name;
        results.push(`${roleName}.${organizationName}.${spaceName}`);
      });
    });
  } catch (error) {
    //
  }
  return results;
}
initApp.getCTX = function () {
  try {
    return window.widget ? window.widget.getValue("ctx_credentials") : "";
  } catch (error) {
    //
  }
};
initApp.store = function () {
  return useDashboardStore();
}

export { initApp as default };
