// All computation/logic for the dashboard lives here (kept separate from
// dashboardData.js, which only holds hardcoded reference data).

import { PALETTE, STATUS_META, MONTHS } from "./dashboardData";

export function seededRandom(seed) {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return () => {
    h = (h * 1664525 + 1013904223) >>> 0;
    return h / 4294967296;
  };
}

// Used by SavedViewsView's demo/mock rows to produce a relative display date.
export function mockDateOffset(daysAgo) {
  const d = new Date();
  d.setDate(d.getDate() - daysAgo);
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function facetsFor(facets, sixw) {
  return facets.filter((f) => f.sixw === sixw);
}

function shortDate(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  return isNaN(d)
    ? iso
    : d.toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
}

function attr(result, name) {
  const a = (result.attributes || []).find((x) => x.name === name);
  return a ? a.value : "";
}

// Rounds each %, keeping the set summing to exactly 100 (largest-remainder method).
function distributePercentages(counts, total) {
  if (!total) return counts.map(() => 0);
  const raw = counts.map((c) => (c / total) * 1000);
  const floors = raw.map(Math.floor);
  let remainder = 1000 - floors.reduce((a, b) => a + b, 0);
  const order = floors
    .map((f, i) => ({ i, rem: raw[i] - f }))
    .sort((a, b) => b.rem - a.rem);
  for (let k = 0; k < remainder; k++) floors[order[k % order.length].i] += 1;
  return floors.map((v) => v / 10);
}

export function mapFederatedResponse(json) {
  const facets = json.facets || [];
  const total = json.infos?.nmatches || 0;

  const statusFacets = facetsFor(facets, "ds6w:what/ds6w:status");
  const statusPcts = distributePercentages(
    statusFacets.map((f) => f.count),
    total,
  );
  const kpis = statusFacets
    .map((f, i) => {
      const key = String(f.object).split(".").pop();
      const meta = STATUS_META[key] || {
        label: key.replace(/_/g, " "),
        icon: "mdi-shape-outline",
        color: PALETTE[i % PALETTE.length],
      };
      return {
        label: meta.label,
        raw: f.object,
        value: f.count,
        pct: statusPcts[i],
        icon: meta.icon,
        color: meta.color,
      };
    })
    .sort((a, b) => b.value - a.value);

  const monthFacets = facetsFor(facets, "ds6w:when/ds6w:created").filter((f) =>
    /^\d{4}\/\d{2}$/.test(f.object),
  );
  const line = monthFacets
    .sort((a, b) => a.object.localeCompare(b.object))
    .map((f) => ({
      label: MONTHS[parseInt(f.object.split("/")[1], 10) - 1],
      raw: f.object,
      value: f.count,
    }));
  const createdMonths = line.map((l) => ({
    label: `${l.label} (${l.value})`,
    raw: l.raw,
  }));

  const modifiedMonths = facetsFor(facets, "ds6w:when/ds6w:modified")
    .filter((f) => /^\d{4}\/\d{2}$/.test(f.object))
    .sort((a, b) => a.object.localeCompare(b.object))
    .map((f) => ({
      label: `${MONTHS[parseInt(f.object.split("/")[1], 10) - 1]} (${f.count})`,
      raw: f.object,
    }));

  const collaborativeSpaces = facetsFor(
    facets,
    "ds6w:where/ds6w:context/ds6w:project",
  ).map((f) => ({ label: `${f.object} (${f.count})`, raw: f.object }));

  const lastModifiedByUsers = facetsFor(
    facets,
    "ds6w:who/ds6w:lastModifiedBy",
  ).map((f) => ({ label: `${f.object} (${f.count})`, raw: f.object }));

  const owners = facetsFor(facets, "ds6w:who/ds6w:responsible")
    .map((f) => ({ name: f.object, raw: f.object, value: f.count }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 10);

  const policyFacets = facetsFor(facets, "ds6w:what/ds6w:policy");
  const policyTotal = policyFacets.reduce((s, f) => s + f.count, 0);
  const policyPcts = distributePercentages(
    policyFacets.map((f) => f.count),
    policyTotal,
  );
  const policies = policyFacets.map((f, i) => ({
    label: f.object,
    raw: f.object,
    value: f.count,
    pct: policyPcts[i],
    color: PALETTE[i % PALETTE.length],
  }));

  const results = (json.results || []).map((r) => ({
    title: attr(r, "ds6w:label"),
    owner: attr(r, "owner") || attr(r, "ds6w:responsibleUid"),
    modified: shortDate(
      attr(r, "ds6w:when/ds6w:modified")),
    createdDate: shortDate(attr(r, "ds6w:when/ds6w:created")),
    status: String(attr(r, "ds6w:what/ds6w:status") || "")
      .split(".")
      .pop(),
    policy: attr(r, "ds6w:what/ds6w:policy"),
    revision: attr(r, "ds6wg:revision"),
    name: attr(r, "ds6w:identifier"),
    project: attr(r, "ds6w:where/ds6w:context/ds6w:project"),
    type: attr(r, "ds6w:type") ||  attr(r, "ds6w:what/ds6w:policy"),
    description: attr(r, "ds6w:description") || attr(r, "dcterms:description"),
    lastModifiedBy: attr(r, "ds6w:lastModifiedBy"),
    fileSize: attr(r, "ds6wg:filesize"),
    dataSource: attr(r, "ds6w:dataSource"),
    community: attr(r, "ds6w:community"),
    originator: attr(r, "ds6w:originator"),
    repository: attr(r, "ds6w:repository"),
    resourceid: attr(r, "resourceid"),
  }));

  return {
    total,
    kpis,
    line: line.map((l) => l.value),
    lineCategories: line.map((l) => l.label),
    lineRaw: line.map((l) => l.raw),
    owners,
    policies,
    results,
    createdMonths,
    modifiedMonths,
    collaborativeSpaces,
    lastModifiedByUsers,
    facets,
  };
}

// Shared by every chart component (donut/bar/line) so drill-down payloads are
// built the same way regardless of chart type.
export function buildDrillPayload(chart, index) {
  const category = chart.categories[index];
  const value = chart.series[index];
  return {
    chartId: chart.id,
    chartTitle: chart.title,
    label: `${chart.title} = ${category}`,
    raw: chart.rawCategories ? chart.rawCategories[index] : category,
    count: value,
  };
}

export function mapFacet(facets, facetKey) {
  return facetsFor(facets, facetKey)
    .map((f) => ({
      label: String(f.object).split(".").pop(),
      raw: f.object,
      value: f.count,
    }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 10);
}
export function mapDateFacet(facets, facetKey) {
  return facetsFor(facets, facetKey)
    .filter((f) => /^\d{4}\/\d{2}$/.test(f.object))
    .sort((a, b) => a.object.localeCompare(b.object))
    .map((f) => ({
      label: `${MONTHS[parseInt(f.object.split("/")[1], 10) - 1]} ${
        f.object.split("/")[0]
      }`,
      raw: f.object,
      value: f.count,
    }));
}
